<?php
/** Import the current HTML pages as whole MODX templates. CLI only; no chunk/TV extraction. */
if(PHP_SAPI!=='cli'){http_response_code(403);exit;}
if(!in_array('--apply',$argv,true)){echo "Usage: php tools/modx/import-static.php --apply\nExisting ZUBR templates are replaced only on explicit --apply; a snapshot is saved first.\n";exit;}
$root=dirname(__DIR__,2).'/';if(is_file($root.'cms/template-registry.json'))throw new RuntimeException('Legacy whole-HTML import disabled: the site now uses shared templates, chunks and TVs. Edit current CMS elements instead.');define('MODX_API_MODE',true);require $root.'public/index.php';$modx->initialize('mgr');
$manifest=json_decode(file_get_contents($root.'cms/static-pages.json'),true,512,JSON_THROW_ON_ERROR);
$backup=['templates'=>[],'resources'=>[]];foreach($modx->getCollection(MODX\Revolution\modTemplate::class) as $o)$backup['templates'][]=$o->toArray();foreach($modx->getCollection(MODX\Revolution\modResource::class) as $o)$backup['resources'][]=$o->toArray();
file_put_contents($root.'cms/backups/before-import-'.date('Ymd-His').'.json',json_encode($backup,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT));
$category=$modx->getObject(MODX\Revolution\modCategory::class,['category'=>'ZUBR GYM · HTML']);if(!$category){$category=$modx->newObject(MODX\Revolution\modCategory::class);$category->set('category','ZUBR GYM · HTML');if(!$category->save())throw new RuntimeException('Category save failed');}
function setting($modx,$key,$value,$xtype='textfield'){$s=$modx->getObject(MODX\Revolution\modSystemSetting::class,['key'=>$key]);if(!$s){$s=$modx->newObject(MODX\Revolution\modSystemSetting::class);$s->fromArray(['key'=>$key,'namespace'=>'core','area'=>'site','xtype'=>$xtype],'',true,true);}$s->set('value',(string)$value);if(!$s->save())throw new RuntimeException('Setting save failed: '.$key);$modx->setOption($key,$value);}
if(!$modx->getObject(MODX\Revolution\modSnippet::class,['name'=>'ZubrSeoHead']))foreach(['site_name'=>'ZUBR GYM','cultureKey'=>'ru','manager_language'=>'ru','site_url'=>'http://zubr-gym.local/','http_host'=>'zubr-gym.local','friendly_urls'=>1,'use_alias_path'=>1,'friendly_urls_strict'=>1,'automatic_alias'=>0,'use_editor'=>0,'cache_resource'=>1,'welcome_screen'=>0] as $key=>$value)setting($modx,$key,$value);
$seoInstalled=(bool)$modx->getObject(MODX\Revolution\modSnippet::class,['name'=>'ZubrSeoHead']);if($seoInstalled)require_once $root.'cms/elements/Seo.php';
$result=[];$ids=[];$home=$modx->getObject(MODX\Revolution\modResource::class,1);
foreach($manifest['pages'] as $index=>$page){$uri=$page['uri'];$redirect=isset($page['redirect']);$parts=explode('/',trim($uri,'/'));$alias=$uri==='/'?'index':end($parts);$parentUri=$page['parentUri']??($uri==='/'?null:'/'.implode('/',array_slice($parts,0,-1)).'/');if($parentUri==='//')$parentUri='/';$parent=($parentUri&&$parentUri!=='/')?($ids[$parentUri]??null):0;if($parent===null)throw new RuntimeException('Parent missing: '.$parentUri);
$templateId=0;if(!$redirect){$name=mb_substr('ZUBR — '.$page['title'],0,50);$template=$modx->getObject(MODX\Revolution\modTemplate::class,['templatename'=>$name]);if(!$template)$template=$modx->newObject(MODX\Revolution\modTemplate::class);$html=file_get_contents($root.$page['source']);if($html===false)throw new RuntimeException('Source missing');if($seoInstalled)$html=Zubr\Site\Seo::prepareTemplate($html);$template->fromArray(['templatename'=>$name,'description'=>'Полный HTML страницы '.$uri.'. Источник: '.$page['source'].'. Без TV-полей и чанков.','category'=>$category->get('id'),'content'=>$html,'static'=>0]);if(!$template->save())throw new RuntimeException('Template failed: '.$uri);$templateId=$template->get('id');}
$resource=$uri==='/'?$home:$modx->getObject(MODX\Revolution\modResource::class,['context_key'=>'web','uri'=>ltrim($uri,'/')]);if(!$resource)$resource=$modx->newObject($redirect?MODX\Revolution\modWebLink::class:MODX\Revolution\modDocument::class);
$folder=false;foreach($manifest['pages'] as $child)if($child['uri']!==$uri&&$uri!=='/'&&str_starts_with($child['uri'],$uri)){$folder=true;break;}
$resource->fromArray(['pagetitle'=>$page['title'],'longtitle'=>$page['longtitle']??$page['title'],'description'=>$page['description']??'','alias'=>$alias,'uri'=>$uri==='/'?'index':ltrim($uri,'/'),'uri_override'=>str_starts_with($uri,'/club/coaches/')&&$uri!=='/club/coaches/'?0:1,'parent'=>$parent,'class_key'=>$redirect?MODX\Revolution\modWebLink::class:MODX\Revolution\modDocument::class,'template'=>$templateId,'content'=>$redirect?$modx->getOption('site_url').ltrim($page['redirect'],'/'):'','context_key'=>'web','content_type'=>1,'published'=>1,'deleted'=>0,'hidemenu'=>$redirect||($page['hidden']??false)?1:0,'richtext'=>0,'searchable'=>$redirect||($page['hidden']??false)?0:1,'cacheable'=>1,'isfolder'=>$folder?1:0,'menuindex'=>$index]);
if(!$resource->save())throw new RuntimeException('Resource failed: '.$uri);$id=(int)$resource->get('id');$ids[$uri]=$id;$result[]=['id'=>$id,'uri'=>$uri,'template'=>$templateId,'class'=>$resource->get('class_key'),'source'=>$page['source']??null];}
setting($modx,'site_start',$ids['/']);setting($modx,'error_page',$ids['/404/']);setting($modx,'default_template',$result[0]['template']);
$modx->cacheManager->refresh();file_put_contents($root.'cms/import-result.json',json_encode(['resources'=>$result,'count'=>count($result),'mode'=>'whole-html-templates'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));
echo json_encode(['resources'=>count($result),'templates'=>count(array_filter($result,fn($r)=>$r['template']>0)),'home'=>$ids['/'],'error'=>$ids['/404/']],JSON_PRETTY_PRINT).PHP_EOL;
